create table administradores (id uuid primary key default gen_random_uuid(), nome text not null, cpf text unique not null, email text unique not null, senha text not null, telefone text, created_at timestamp default now());
create table funcionarios (id uuid primary key default gen_random_uuid(), foto_url text, nome text not null, cpf text unique not null, telefone_celular text not null, matricula text unique not null, cargo text not null, funcao text not null, departamento text not null, data_admissao date not null, horario_entrada time default '08:00', horario_saida time default '17:00', senha text not null, status text default 'ativo', created_at timestamp default now());
create table registros_ponto (id uuid primary key default gen_random_uuid(), funcionario_id uuid references funcionarios(id), matricula text not null, tipo text check (tipo in ('entrada','saida','saida_almoco','volta_almoco')), timestamp timestamp default now(), data date default current_date, codigo text unique not null);
create table sms_logs (id uuid primary key default gen_random_uuid(), matricula text not null, tipo text not null, telefone text not null, mensagem text not null, status text default 'enviado', timestamp timestamp default now());
create table faltas (id uuid primary key default gen_random_uuid(), funcionario_id uuid references funcionarios(id), data date, motivo text, abonada boolean default false, justificada boolean default false, created_at timestamp default now());
alter table administradores disable row level security; alter table funcionarios disable row level security; alter table registros_ponto disable row level security; alter table sms_logs disable row level security; alter table faltas disable row level security;
